/* setup passive open */ if ((s = socket(PF_INET, SOCK_STREAM, 0)) < 0) { error("simplex-talk: socket"); exit(1); } if ((bind(s, (struct sockaddr *)&sin, sizeof(sin))) < 0) { error("simplex-talk: bind"); exit(1); } listen(s, MAX_PENDING);


/* wait for connection, then receive and print text */ while(1){ if ((new_s = accept(s, (struct sockaddr *)&sin, &len)) < 0) { error("simplex-talk: accept"); exit(1); } while (len = recv(new_s, buf, sizeof(buf), 0))fputs(buf,stdout): close(new_s): } }

